def choose_move(observation):
    w = observation.get('grid_width', 8)
    h = observation.get('grid_height', 8)

    sp = observation.get('self_position', (0, 0))
    op = observation.get('opponent_position', (0, 0))
    sx, sy = sp[0], sp[1]
    ox, oy = op[0], op[1]

    obstacles = observation.get('obstacles', []) or []
    obs = set()
    for p in obstacles:
        if len(p) >= 2:
            obs.add((p[0], p[1]))

    resources = observation.get('resources', []) or []
    if not resources:
        tx, ty = w // 2, h // 2
    else:
        best = None
        for r in resources:
            if len(r) < 2:
                continue
            rx, ry = r[0], r[1]
            d = abs(rx - sx) + abs(ry - sy)
            key = (d, rx, ry)
            if best is None or key < best[0]:
                best = (key, (rx, ry))
        tx, ty = best[1] if best else (w // 2, h // 2)

    cx = 0 if tx == sx else (1 if tx > sx else -1)
    cy = 0 if ty == sy else (1 if ty > sy else -1)

    prefs = [(cx, cy), (cx, 0), (0, cy), (cx, -cy), (-cx, cy), (0, 0)]
    seen = set()
    moves = []
    for dx, dy in prefs:
        if (dx, dy) not in seen and dx in (-1, 0, 1) and dy in (-1, 0, 1):
            seen.add((dx, dy))
            moves.append((dx, dy))
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if (dx, dy) not in seen:
                seen.add((dx, dy))
                moves.append((dx, dy))

    def dist(x, y):
        return abs(tx - x) + abs(ty - y)

    best_move = (0, 0)
    best_score = None
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if nx < 0 or ny < 0 or nx >= w or ny >= h:
            continue
        if (nx, ny) in obs:
            continue
        score = (dist(nx, ny), abs(ox - nx) + abs(oy - ny), nx, ny)
        if best_score is None or score < best_score:
            best_score = score
            best_move = (dx, dy)
    return [best_move[0], best_move[1]]

